<?php use Spirit\AnalyticsAdmin as A; ?>
<section class="panel" id="search-console"><div class="section-title"><div><p class="eyebrow">GOOGLE SEARCH PERFORMANCE</p><h2>Search Console queries</h2></div><a class="button secondary" href="https://search.google.com/search-console" target="_blank" rel="noopener noreferrer">Open Search Console ↗</a></div>
 <p class="muted">Import the Queries CSV from your verified Google Search Console property to see search phrases, clicks, impressions, click-through rate, and average position. This is an aggregate search report, with its own dates, separate from visitor sessions.</p>
